package ssh

import (
	"strings"
	"testing"
)

func TestRenderConfigOutputsHosts(t *testing.T) {
	config := RenderConfig([]Host{
		{
			Alias:               "prod-api",
			HostName:            "10.0.0.12",
			User:                "ubuntu",
			Port:                22,
			IdentityFile:        "~/.ssh/prod.pem",
			ProxyJump:           "bastion",
			ForwardAgent:        true,
			ServerAliveInterval: 30,
		},
		{
			Alias:    "legacy-db",
			HostName: "10.0.0.99",
		},
	})

	wantLines := []string{
		"# Generated by aTerm",
		"Host prod-api",
		"    HostName 10.0.0.12",
		"    User ubuntu",
		"    Port 22",
		"    IdentityFile ~/.ssh/prod.pem",
		"    ProxyJump bastion",
		"    ForwardAgent yes",
		"    ServerAliveInterval 30",
		"Host legacy-db",
		"    HostName 10.0.0.99",
	}
	for _, line := range wantLines {
		if !strings.Contains(config, line) {
			t.Fatalf("rendered config missing %q:\n%s", line, config)
		}
	}
}

func TestRenderConfigIncludesEmptyHeader(t *testing.T) {
	config := RenderConfig(nil)

	if !strings.Contains(config, "# Generated by aTerm") {
		t.Fatalf("rendered config missing header:\n%s", config)
	}
}
